<script lang="ts">
 import {onMount,untrack,tick} from 'svelte';
 import FaceSourcePreview from './FaceSourcePreview.svelte';
 import * as api from '../../bindings';
 import ErrorNotice from '../../ErrorNotice.svelte';
 import ResourcePanel from '../resources/ResourcePanel.svelte';
 import FaceTile from './FaceTile.svelte';
 import type {CaseOperations} from '../operations/controller.svelte';
 let {generation,operations,active,onopen,oncollect,selectedArtifact='',initialFace=null}:{generation:number;operations:CaseOperations;active:boolean;onopen:(kind:string,id:string,page?:number)=>void;oncollect?:(url:string)=>void;selectedArtifact?:string;initialFace?:api.FaceView|null}=$props();
 let status=$state<api.FaceStatusView|null>(null),artifacts=$state<api.ArtifactRowView[]>([]),artifact=$state(''),artifactOffset=$state(0),artifactTotal=$state(0);
 let faces=$state<api.FacePageView|null>(null),faceOffset=$state(0),selected=$state<api.FaceView|null>(null),comparison=$state<api.FaceView|null>(null);
 let results=$state<api.FaceSearchView|null>(null),related=$state<api.SearchView|null>(null),groups=$state<api.FaceGroupView[]>([]),groupOffset=$state(0);
 let query=$state(''),textMode=$state('lexical'),both=$state(false),threshold=$state(0.363),page=$state(1),start=$state(0),end=$state<number|undefined>(undefined);
 let error=$state<api.CommandError|null>(null),loading=$state(false),searching=$state(false),busyReview=$state(false),showGroups=$state(false);
 let reviewFace=$state<api.FaceView|null>(null),person=$state(''),newName=$state(''),personQuery=$state(''),people=$state<Array<{entity_id:string;display_name:string;type_key:string}>>([]),rationale=$state('');
 let consent=$state(false),health=$state(''),webPage=$state(1),web=$state<api.DiscoveryView|null>(null);
 let selectedBatch=$state<string[]>([]);let live=true,version=0,searchVersion=0;let previousJob='';let appearanceVersion=0;let root=$state<HTMLElement|null>(null);
 function attachmentLabel(row:api.ArtifactRowView){const value=row.canonical_locator??row.artifact_id;const name=value.split(/[\\/]/).pop()??value;try{return decodeURIComponent(name);}catch{return name;}}
 const supported=(m:string)=>['image/jpeg','image/png','image/webp','image/tiff','application/pdf','video/mp4','video/quicktime','video/webm','video/x-matroska','video/x-msvideo'].includes(m);
 let chosenArtifact=$derived(artifacts.find(a=>a.artifact_id===artifact));
 let isVideo=$derived(chosenArtifact?.media_type.startsWith('video/')??false);
 onMount(()=>()=>{live=false;version++;searchVersion++;});
 $effect(()=>{if(active)void refresh();});
 $effect(()=>{const face=initialFace;if(face)untrack(()=>{searchVersion++;appearanceVersion++;searching=false;results=null;comparison=null;selected=face;artifact=face.artifact_id;faceOffset=0;void loadFaces();});});
 $effect(()=>{const id=selectedArtifact;if(id)untrack(()=>{artifact=id;faceOffset=0;void loadFaces();});});
 $effect(()=>{query;webPage;consent=false;});
 $effect(()=>{const job=operations.operation;if(job&&job.status!=='running'&&job.operation_id!==previousJob){previousJob=job.operation_id;if(active)void refresh();if(operations.result&&'hits' in operations.result&&'query' in operations.result)web=operations.result as unknown as api.DiscoveryView;}});
 async function refresh(){const current=++version;loading=true;try{const [s,a]=await Promise.all([api.faceStatus(generation),api.artifactPage(artifactOffset)]);if(!live||current!==version)return;status=s;artifacts=a.rows;artifactTotal=a.total;await loadFaces();if(selected){const updated=faces?.faces.find(f=>f.id===selected?.id);if(updated)selected=updated;}if(showGroups)groups=await api.faceGroups(generation,groupOffset);}catch(raw){if(live&&current===version)error=api.asCommandError(raw);}finally{if(live&&current===version)loading=false;}}
 async function loadFaces(){const id=artifact,offset=faceOffset;try{const value=await api.facePage(generation,id,offset);if(live&&artifact===id&&faceOffset===offset)faces=value;}catch(raw){if(live)error=api.asCommandError(raw);}}
 function chooseArtifact(event:Event){searchVersion++;appearanceVersion++;searching=false;artifact=(event.currentTarget as HTMLSelectElement).value;faceOffset=0;selected=null;comparison=null;results=null;void loadFaces();}
 async function showAppearance(face:api.FaceView,source=false){const version=++appearanceVersion;try{const full=face.crop_png?face:await api.faceRead(generation,face.id);if(!live||version!==appearanceVersion)return;comparison=full;await tick();root?.querySelector(source?'section[aria-label="Located face source preview"]':'.comparison')?.scrollIntoView({block:'center'});}catch(raw){if(live)error=api.asCommandError(raw);}}
 function choose(face:api.FaceView){searchVersion++;appearanceVersion++;searching=false;selected=face;comparison=null;results=null;}
 function openSource(face:api.FaceView){onopen(face.timestamp_ms!==null?'artifact':'document',face.artifact_id,face.page);}
 async function analyze(ids:string[]){if(!ids.length)return;error=null;await operations.run('face_analyze',{version:1,artifact_ids:ids,page:page-1,start_ms:Math.round(start*1000),end_ms:end===undefined?null:Math.round(end*1000)} satisfies api.FaceAnalysisRequest);}
 async function search(offset=0){if(searching)return;const current=++searchVersion;searching=true;error=null;try{if(selected){const value=await api.faceSearch(generation,{version:1,face_id:selected.id,query,text_mode:textMode,both,threshold,offset,limit:20});if(live&&current===searchVersion){results=value;related=value.related;}}else if(query.trim()){const value=textMode==='lexical'?await api.searchCase({query,limit:50}):(await api.semanticSearch(generation,{version:1,mode:textMode,search:{query,limit:50,offset:0,kinds:[],facets:[],include_superseded:false,resolve_merged:true,typeahead:false}})).results;if(live&&current===searchVersion){related=value;results=null;}}}catch(raw){if(live&&current===searchVersion)error=api.asCommandError(raw);}finally{if(live&&current===searchVersion)searching=false;}}
 async function auto(enabled:boolean){try{await api.faceAutoAnalyze(generation,enabled);await refresh();}catch(raw){error=api.asCommandError(raw);}}
 async function findPeople(){try{people=(await api.entityPage()).rows.filter(p=>p.type_key==='person');if(personQuery.trim()){const hits=(await api.searchCase({query:personQuery,kinds:['entity'],limit:50})).hits;people=[];for(const hit of hits){const e=await api.entity(hit.subject_id);if(e.type_key==='person')people.push({entity_id:e.entity_id,type_key:e.type_key,display_name:e.display_name});}}}catch(raw){error=api.asCommandError(raw);}}
 function review(face:api.FaceView){reviewFace=face;rationale='';person=face.entity_id??'';newName='';void findPeople();}
 async function saveReview(decision:string,groupId:string|null=null,face=reviewFace){if(!face||!rationale.trim()||busyReview)return;busyReview=true;error=null;try{let entity=person||null;if(decision==='accepted'&&newName.trim()){entity=await api.facePersonCreate(generation,{face_id:face.id,name:newName.trim(),rationale});newName='';person=entity;reviewFace=null;await refresh();if(selected)await search();return;}await api.faceReview(generation,{face_id:face.id,entity_id:groupId?null:entity,group_id:groupId,decision,rationale});reviewFace=null;await refresh();if(selected)await search();}catch(raw){error=api.asCommandError(raw);}finally{busyReview=false;}}
 async function browser(provider:string){try{await api.researchBrowser(provider,query);}catch(raw){error=api.asCommandError(raw);}}
 async function checkHealth(){if(!consent)return;try{health=await api.discoveryHealth();}catch(raw){error=api.asCommandError(raw);}}
 async function discover(){if(!consent||!query.trim())return;await operations.run('web_discover',{query,page:webPage,consent} satisfies api.DiscoveryRequest);}
 async function groupPage(group:api.FaceGroupView,offset:number){try{const value=await api.faceGroupMembers(generation,group.id,offset);if(live)groups=groups.map(g=>g.id===group.id?{...g,faces:value.page.faces,member_total:value.page.total,member_offset:value.page.offset}:g);}catch(raw){error=api.asCommandError(raw);}}
 function toggleBatch(id:string,checked:boolean){selectedBatch=checked?[...selectedBatch,id]:selectedBatch.filter(x=>x!==id);}
</script>
<section bind:this={root} class="faces-workspace" aria-label="Faces and related evidence">
 <header><h3>Faces and related evidence</h3><p>Compare a face within this case, then follow names, topics, and source material.</p></header>
 {#if error}<ErrorNotice {error}/>{/if}
 {#if status}<p class="coverage" role="status">{status.faces} current faces · {status.analyzed_artifacts} of {status.eligible_artifacts} eligible attachments analyzed. PDF pages and video frames can have partial coverage.</p>
 <details><summary>Local analysis and resources</summary>
  <p>{status.limitation}</p>
  {#if !status.native_available}<p>Face worker unavailable. Prepare and package the native face worker on Apple Silicon macOS.</p>{/if}
  {#if !status.resources_present}<p>Install both reviewed resources, face_detection_yunet and face_recognition_sface, before analyzing.</p>{/if}
  <ResourcePanel/>
  <label class="check"><input type="checkbox" checked={status.auto_analyze} onchange={e=>void auto(e.currentTarget.checked)}/>Analyze new supported imports automatically in this case</label>
  <p>Automatic PDF analysis covers the first page. Videos sample every two seconds, up to 1,800 frames. Manual jobs can select other pages or ranges.</p>
  <button type="button" onclick={()=>void refresh()}>Recheck installed resources</button>
 </details>{/if}
 <div class="input-grid">
  <label>Photo or attachment<select bind:value={artifact} onchange={chooseArtifact}><option value="">All indexed evidence</option>{#each artifacts.filter(a=>supported(a.media_type)) as a}<option value={a.artifact_id}>{attachmentLabel(a)} · {a.media_type}</option>{/each}</select></label>
  <label>Names or topics<input bind:value={query} maxlength="4096" placeholder="Name, alias, organization, or subject"/></label>
 </div>
 {#if chosenArtifact?.canonical_locator}<button type="button" onclick={()=>{query=(chosenArtifact!.canonical_locator!.split(/[\\/]/).pop()??'').replace(/\.[^.]+$/,'');}}>Use attachment filename as query</button>{/if}
 <div class="toolbar"><button type="button" disabled={artifactOffset===0||loading} onclick={()=>{searchVersion++;appearanceVersion++;searching=false;artifactOffset=Math.max(0,artifactOffset-50);artifact='';selected=null;comparison=null;faceOffset=0;void refresh();}}>Previous attachments</button><span>{artifactOffset+1}–{Math.min(artifactOffset+50,artifactTotal)} of {artifactTotal}</span><button type="button" disabled={artifactOffset+50>=artifactTotal||loading} onclick={()=>{searchVersion++;appearanceVersion++;searching=false;artifactOffset+=50;artifact='';selected=null;comparison=null;faceOffset=0;void refresh();}}>Next attachments</button></div>
 {#if artifact}
 <div class="toolbar analysis-controls">
  {#if isVideo}<label>Start seconds<input type="number" min="0" max="86399" step="0.1" bind:value={start}/></label><label>End seconds (optional)<input type="number" min={start+0.1} max="86400" step="0.1" bind:value={end}/></label>{:else}<label>PDF page / image page<input type="number" min="1" max="65536" step="1" bind:value={page}/></label>{/if}
  <button type="button" disabled={operations.busy||!status?.resources_present||!status?.native_available||!Number.isInteger(page)||page<1||start<0||(end!==undefined&&end<=start)} onclick={()=>void analyze([artifact])}>Analyze faces</button>
 </div>
 <details><summary>Analyze a batch of attachments</summary><p>The selected page or time range applies to every attachment in this batch. A failed item preserves the previous index for the whole batch.</p><ul class="batch">{#each artifacts.filter(a=>supported(a.media_type)) as a}<li><label class="check"><input type="checkbox" checked={selectedBatch.includes(a.artifact_id)} onchange={e=>toggleBatch(a.artifact_id,e.currentTarget.checked)}/>{attachmentLabel(a)}</label></li>{/each}</ul><button type="button" disabled={operations.busy||!selectedBatch.length||selectedBatch.length>100} onclick={()=>void analyze(selectedBatch)}>Analyze selected attachments ({selectedBatch.length})</button></details>
 {/if}
 {#if operations.busy}<p role="status">{operations.operation?.stage??'Starting analysis…'}</p>{#if operations.operation?.cancellable}<button type="button" onclick={operations.cancel}>Cancel job</button>{/if}{/if}
 {#if faces?.faces.length}<h4>Choose a face</h4><div class="face-strip">{#each faces.faces as face}<FaceTile {face} selected={selected?.id===face.id} onselect={choose} onopen={openSource}/>{/each}</div>
 <div class="toolbar"><button type="button" disabled={faceOffset===0} onclick={()=>{faceOffset=Math.max(0,faceOffset-50);void loadFaces();}}>Previous faces</button><span>{faceOffset+1}–{Math.min(faceOffset+50,faces.total)} of {faces.total}</span><button type="button" disabled={faceOffset+50>=faces.total} onclick={()=>{faceOffset+=50;void loadFaces();}}>Next faces</button></div>
 {:else if !loading}<p>No indexed faces here. Analyze a supported attachment, or choose another attachment. No detected faces does not establish that an image contains no people.</p>{/if}
 {#if faces?.limitations.length}<details><summary>Page and frame coverage</summary>{#each faces.limitations as limitation}<p>{limitation}</p>{/each}</details>{/if}
 <form onsubmit={e=>{e.preventDefault();void search();}}>
 <div class="toolbar"><label>Text retrieval<select bind:value={textMode}><option value="lexical">Words and OCR</option><option value="semantic">Semantic · requires index</option><option value="hybrid">Hybrid · requires index</option></select></label>
 {#if selected}<label>Minimum face similarity<input type="number" min="-1" max="1" step="0.001" bind:value={threshold}/></label><label class="check"><input type="checkbox" bind:checked={both}/>Both face and text in the same attachment</label>{/if}
 <button disabled={searching||(!selected&&!query.trim())||(both&&!query.trim())}>{searching?'Searching…':'Find matches'}</button>{#if selected}<button type="button" onclick={()=>{searchVersion++;appearanceVersion++;searching=false;selected=null;comparison=null;results=null;}}>Clear selected face</button>{/if}</div>
 </form>
 {#if selected}<section class="comparison" aria-label="Face comparison"><div><h4>Query face</h4><FaceTile face={selected} onselect={()=>review(selected!)} onopen={openSource}/><button type="button" onclick={()=>review(selected!)}>Review person link</button>{#if selected.entity_name}<button type="button" onclick={()=>{query=selected!.entity_name!;}}>Use reviewed name in query</button>{/if}</div>{#if comparison}<div><h4>Candidate face</h4><FaceTile face={comparison} onselect={()=>review(comparison!)} onopen={openSource}/><button type="button" onclick={()=>review(comparison!)}>Review person link</button></div>{/if}</section>{/if}
 {#if results}<section aria-label="Face matches"><h4>Face matches ({results.total} attachments)</h4><p>Cosine similarity orders candidates. It is not the probability that two faces share an identity.</p>{#if results.truncated}<p>Candidate or text traversal reached a bound; additional matches may exist.</p>{/if}
 {#each results.matches as match}<article class="match"><FaceTile face={match.face} onselect={face=>void showAppearance(face)} onopen={openSource}/><div><strong>Similarity {match.similarity.toFixed(3)}</strong><p>{match.occurrence_count} matching appearance(s) in this attachment.</p><button type="button" onclick={()=>void showAppearance(match.face)}>Compare side by side</button><button type="button" onclick={()=>review(match.face)}>Review person link</button>{#if match.occurrences.length}<details><summary>Matching appearances (up to 50 shown)</summary>{#each [match.face,...match.occurrences] as appearance}<button type="button" onclick={()=>void showAppearance(appearance,true)}>{appearance.timestamp_ms!==null?`${(appearance.timestamp_ms/1000).toFixed(2)} seconds`:`Page ${appearance.page+1}`}</button>{/each}</details>{/if}{#if match.occurrence_count>50}<p>Showing 50 of {match.occurrence_count} matching appearances. Every indexed timestamp is retained in the paginated source face browser.</p><button type="button" onclick={()=>{artifact=match.face.artifact_id;faceOffset=0;void loadFaces();}}>Browse all faces in this attachment</button>{/if}</div></article>{/each}
 {#if !results.matches.length}<p>No candidates meet this threshold within indexed coverage.</p>{/if}
 <div class="toolbar"><button type="button" disabled={results.offset===0||searching} onclick={()=>void search(Math.max(0,results!.offset-20))}>Previous matches</button><button type="button" disabled={results.offset+20>=results.total||searching} onclick={()=>void search(results!.offset+20)}>Next matches</button></div></section>{/if}
 {#if related}<section aria-label="Related local evidence"><h4>Related names and topics ({related.total})</h4><p>{related.coverage.incomplete} attachment(s) have incomplete text coverage. Showing {related.hits.length} results.</p><ul>{#each related.hits as hit}<li><button type="button" onclick={()=>onopen(hit.subject_kind,hit.subject_id)}>{hit.title}</button><p>{hit.snippet}</p></li>{/each}</ul></section>{/if}
 <details ontoggle={e=>{showGroups=e.currentTarget.open;if(showGroups)void refresh();}}><summary>Suggested face groups</summary><p>Groups require pairwise similarity of at least 0.5. Every person label still requires review.</p><button type="button" disabled={operations.busy} onclick={()=>operations.run('face_regroup',{})}>Build suggested groups</button>
 {#each groups as group}<section class="suggestion" aria-label="Suggested group"><div class="face-strip">{#each group.faces as face}<div><FaceTile {face} onselect={choose} onopen={openSource}/><button type="button" onclick={()=>review(face)}>Review person link</button><button type="button" onclick={()=>{reviewFace=face;rationale='Excluded from suggested group after visual review';void saveReview('excluded',group.id,face);}}>Split out this face</button></div>{/each}</div><div class="toolbar"><span>{group.member_offset+1}–{Math.min(group.member_offset+12,group.member_total)} of {group.member_total} group members</span><button type="button" disabled={group.member_offset===0} onclick={()=>void groupPage(group,Math.max(0,group.member_offset-12))}>Previous group members</button><button type="button" disabled={group.member_offset+12>=group.member_total} onclick={()=>void groupPage(group,group.member_offset+12)}>Next group members</button></div></section>{/each}
 <div class="toolbar"><button type="button" disabled={groupOffset===0} onclick={()=>{groupOffset=Math.max(0,groupOffset-20);void refresh();}}>Previous groups</button><button type="button" disabled={groups.length<20} onclick={()=>{groupOffset+=20;void refresh();}}>Next groups</button></div></details>
 {#if reviewFace}<section class="review" aria-label="Review person link"><h4>Review a face-to-person link</h4><p>Choose a person or create one from your evidence, and explain your assessment.</p><FaceTile face={reviewFace} onopen={openSource}/><div class="input-grid"><label>Find person<input bind:value={personQuery}/></label><button type="button" onclick={()=>void findPeople()}>Find people</button><label>Existing person<select bind:value={person}><option value="">Choose a person</option>{#each people as p}<option value={p.entity_id}>{p.display_name}</option>{/each}</select></label><label>Or create person<input bind:value={newName} maxlength="256"/></label></div><label>Review rationale<textarea bind:value={rationale} maxlength="8192" required></textarea></label><div class="toolbar"><button type="button" disabled={busyReview||!rationale.trim()||(!person&&!newName.trim())} onclick={()=>void saveReview('accepted')}>Accept person link</button><button type="button" disabled={busyReview||!rationale.trim()} onclick={()=>void saveReview('rejected')}>Reject link</button><button type="button" disabled={busyReview||!rationale.trim()} onclick={()=>void saveReview('unlinked')}>Remove current link</button><button type="button" onclick={()=>reviewFace=null}>Close review</button></div></section>{/if}
 {#if comparison??selected}<FaceSourcePreview {generation} face={(comparison??selected)!} onselect={choose}/>{/if}
 <section class="web" aria-label="Web discovery"><h4>Discover related material online</h4><p>Your editable name/topic query is sent through local SearXNG to upstream search engines. Photos, attachments, and face embeddings stay in this app.</p><label class="check"><input type="checkbox" bind:checked={consent}/>Authorize this query: “{query}” (page {webPage}). Service check sends the test query “SearXNG”.</label><div class="toolbar"><label>Web results page<input type="number" min="1" max="100" step="1" bind:value={webPage}/></label><button type="button" disabled={!consent||!query.trim()||!operations.online||operations.busy} onclick={()=>void discover()}>Search web and save response</button><button type="button" disabled={!consent||!operations.online} onclick={()=>void checkHealth()}>Check local search service</button></div>{#if health}<p role="status">{health}</p>{/if}
 <details><summary>Set up free local web discovery</summary><p>Install Docker Desktop, then run <code>docker compose up -d</code> from <code>deploy/searxng</code> in the project. SearXNG must listen on 127.0.0.1:8088 with JSON enabled. Enable online mode in Kokin before searching. Upstream engines may limit requests.</p></details>
 <div class="toolbar"><button type="button" disabled={!query.trim()} onclick={()=>void browser('google')}>Search query in Google</button><button type="button" disabled={!query.trim()} onclick={()=>void browser('bing')}>Search query in Bing</button></div>
 {#if web}<p>Web query: {web.query}</p><p>{web.limitation}</p><button type="button" onclick={()=>onopen('artifact',web!.artifact_id)}>Inspect saved search response</button><ul>{#each web.hits as hit}<li><strong>{hit.title}</strong><p>{hit.snippet}</p><code>{hit.url}</code><button type="button" onclick={()=>{operations.url=hit.url;oncollect?.(hit.url);}}>Use URL in collection controls</button></li>{/each}</ul>{/if}
 <h4>External face search</h4><p>Open a provider, then upload a photo yourself if you choose. Provider limits and fees apply; Kokin sends no photo when opening these sites.</p><div class="toolbar"><button type="button" onclick={()=>void browser('pimeyes')}>Open PimEyes</button><button type="button" onclick={()=>void browser('facecheck')}>Open FaceCheck</button></div>
 </section>
</section>
<style>
 .faces-workspace{margin:24px 0;padding-top:24px;border-top:1px solid var(--border);min-width:0}h3{font-size:22px;margin:0 0 10px}h4{font-size:16px;margin:26px 0 12px}p{color:var(--foreground-secondary);line-height:1.6;max-width:75ch}.coverage{font-size:13px}.input-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin:20px 0}label{display:grid;gap:8px;font-size:13px}input,select,textarea{max-width:100%;box-sizing:border-box}input[type=number]{width:8rem}textarea{min-height:90px;width:100%}.toolbar{display:flex;flex-wrap:wrap;gap:12px;align-items:end;margin:16px 0}.toolbar span{align-self:center;font-size:12px;color:var(--foreground-secondary)}.check{display:flex;align-items:start;line-height:1.6;gap:10px}.check input{margin-top:4px}.face-strip{display:flex;flex-wrap:wrap;gap:24px;padding:10px 2px}.comparison{display:flex;gap:48px;flex-wrap:wrap;padding:8px 0 24px}.comparison>div{max-width:280px;display:grid;justify-items:start;gap:10px}.comparison h4{margin-bottom:4px}.match{display:flex;gap:24px;padding:20px 0;border-top:1px solid var(--border)}.match>div{min-width:0}.match button{margin:4px 8px 4px 0}.review,.web,.suggestion{margin-top:24px;padding-top:20px;border-top:1px solid var(--border)}details{margin:20px 0}summary{cursor:pointer;font-weight:600}li{margin:12px 0;overflow-wrap:anywhere}ul.batch{list-style:none;padding:0;max-height:240px;overflow:auto}code{font-size:12px;overflow-wrap:anywhere}button:focus-visible,input:focus-visible,select:focus-visible,summary:focus-visible,textarea:focus-visible{outline:2px solid var(--accent);outline-offset:3px}@media(max-width:800px){.input-grid{grid-template-columns:1fr}.match{gap:16px}.comparison{gap:24px}}
</style>
